/**
 * OData literal helpers for the generated functions and function-backed messages.
 * Generated by tools/generate-sdk-types (function-request.ts). Do not edit by hand.
 *
 * `formatParameterAlias` and `formatRecordPath` call `odataLiteral` in
 * `@mohsinonxrm/dataverse-sdk-core` (#254), as the ones in
 * `@mohsinonxrm/dataverse-sdk-entities-runtime` do, so both code generators write the same
 * literals.
 */
import {
  odataLiteral,
  type ODataParameterKind,
  type ODataRecordReference,
} from "@mohsinonxrm/dataverse-sdk-core";

/** Structural kind of an operation parameter, as the generator classifies it. */
export type ParameterKind = ODataParameterKind;

/**
 * The path of one record, `<entity set>(<id>)`, for binding an operation to it.
 *
 * @throws DataverseInvalidRequestError when the reference has no `entitySetName`.
 */
export function formatRecordPath(reference: ODataRecordReference): string {
  return odataLiteral.recordPath(reference);
}

/**
 * Format a function parameter value as the OData literal for a parameter alias (core's
 * `odataLiteral.parameter()`). The caller URL-encodes the result.
 */
export function formatParameterAlias(
  value: unknown,
  odataType: string,
  kind: ParameterKind = "PrimitiveType"
): string {
  return odataLiteral.parameter(value, odataType, kind);
}
